using System.Collections.Generic;
using UnityEditor;
using UnityEngine;


// MARK: ! AI disclaimer
// All code in this file was generated by Claude Opus 5



// Draws the 47 shape slots laid out where they belong rather than in a list, because no naming
// scheme survives "north edge with a south east notch". Each cell carries a 3x3 of the
// neighbourhood it stands for:
//
//     bright  a neighbour is there          dark    nothing there
//     faint   a diagonal that cannot be seen from here, so its state does not matter
//
// A greyed cell is the same slot as its opposite number, drawn only to keep the shape of the
// diagram - edit the one across from it. Leave a slot empty and it falls back to a fill.
[CustomPropertyDrawer(typeof(TerrainEdges))]
public class TerrainEdgesDrawer : PropertyDrawer
{
    private const float CELL = 42.0f;
    private const float PIP = 5.0f;
    private const float PIP_GAP = 1.0f;
    private const float DIAGRAM = PIP * 3.0f + PIP_GAP * 2.0f;

    private static readonly Color Filled = new Color(0.78f, 0.80f, 0.83f);
    private static readonly Color Empty = new Color(0.20f, 0.21f, 0.23f);
    private static readonly Color Moot = new Color(0.36f, 0.37f, 0.40f, 0.45f);
    private static readonly Color Centre = new Color(0.45f, 0.72f, 0.95f);

    private const int N = TerrainEdges.N;
    private const int NE = TerrainEdges.NE;
    private const int E = TerrainEdges.E;
    private const int SE = TerrainEdges.SE;
    private const int S = TerrainEdges.S;
    private const int SW = TerrainEdges.SW;
    private const int W = TerrainEdges.W;
    private const int NW = TerrainEdges.NW;
    private const int CARD = TerrainEdges.CARDINALS;


    private const int GAP = -1;
    private const int FILL_PREVIEW = -2;


    private struct Cell
    {
        public int slot;     // or GAP / FILL_PREVIEW
        public string note;  // set means the cell is shown but cannot be edited, and says why
    }


    private struct Section
    {
        public string title;
        public string hint;
        public int columns;
        public Cell[] cells;
    }


    private static readonly Section[] Layout = BuildLayout();


    // Each cell is written as the neighbourhood it represents, then resolved to whichever slot
    // that collapses onto. Nothing here hard codes a slot index
    private static Cell Fill(int mask) { return new Cell { slot = TerrainEdges.SlotForMask(mask) }; }
    private static Cell Mirror(int mask) { return new Cell { slot = TerrainEdges.SlotForMask(mask), note = "edit the cell opposite" }; }
    private static Cell Gap() { return new Cell { slot = GAP }; }
    private static Cell Preview() { return new Cell { slot = FILL_PREVIEW, note = "a surrounded cell always takes a random sprite from Variants" }; }


    private static Section[] BuildLayout()
    {
        return new[]
        {
            // the plain ring, exactly how a tileset page is drawn
            new Section
            {
                title = "Fill and its edges",
                hint = "the centre shows the first Variant, it is not a slot",
                columns = 3,
                cells = new[]
                {
                    Fill(E | S | SE),           Fill(E | S | W | SE | SW),  Fill(S | W | SW),
                    Fill(N | E | S | NE | SE),  Preview(),                  Fill(N | S | W | NW | SW),
                    Fill(N | E | NE),           Fill(N | E | W | NE | NW),  Fill(N | W | NW),
                },
            },

            // surrounded on all four sides, with holes on the diagonals
            new Section
            {
                title = "Inner corners",
                hint = "all four sides filled, diagonals missing",
                columns = 3,
                cells = new[]
                {
                    Fill(CARD | NE | SE | SW),  Fill(CARD | SE | SW),       Fill(CARD | NW | SE | SW),
                    Fill(CARD | NE | SE),       Fill(CARD),                 Fill(CARD | NW | SW),
                    Fill(CARD | NE | SE | NW),  Fill(CARD | NE | NW),       Fill(CARD | NE | SW | NW),
                },
            },

            new Section
            {
                title = "Inner corners, opposite and triple",
                hint = "the ones that want more than one notch at a time",
                columns = 6,
                cells = new[]
                {
                    Fill(CARD | NE | SW), Fill(CARD | NW | SE),
                    Fill(CARD | SW), Fill(CARD | NW), Fill(CARD | NE), Fill(CARD | SE),
                },
            },

            // one side missing, and one or both of the diagonals that still matter
            new Section
            {
                title = "Notched sides",
                hint = "rows are which side is open, columns are which notch",
                columns = 3,
                cells = new[]
                {
                    Fill(E | S | W | SW),  Fill(E | S | W | SE),  Fill(E | S | W),
                    Fill(N | S | W | SW),  Fill(N | S | W | NW),  Fill(N | S | W),
                    Fill(N | E | W | NW),  Fill(N | E | W | NE),  Fill(N | E | W),
                    Fill(N | E | S | SE),  Fill(N | E | S | NE),  Fill(N | E | S),
                },
            },

            // corners whose diagonal is also open, ringed by the two corridors
            new Section
            {
                title = "Open corners and corridors",
                hint = "a cell sits where its openings are, so the north-south corridor is on the sides",
                columns = 3,
                cells = new[]
                {
                    Fill(E | S),      Fill(E | W),    Fill(S | W),
                    Mirror(N | S),    Gap(),          Fill(N | S),
                    Fill(N | E),      Mirror(E | W),  Fill(N | W),
                },
            },

            new Section
            {
                title = "Tips and isolated",
                hint = "the only neighbour is in that direction",
                columns = 3,
                cells = new[]
                {
                    Gap(),      Fill(N),  Gap(),
                    Fill(W),    Fill(0),  Fill(E),
                    Gap(),      Fill(S),  Gap(),
                },
            },
        };
    }


    public override float GetPropertyHeight(SerializedProperty property, GUIContent label)
    {
        float line = EditorGUIUtility.singleLineHeight;
        if (!property.isExpanded) return line;

        float gap = EditorGUIUtility.standardVerticalSpacing;
        float height = line + gap;

        foreach (Section section in Layout)
        {
            int rows = Mathf.CeilToInt(section.cells.Length / (float)section.columns);
            height += line + line + gap + rows * (RowHeight() + gap) + gap;
        }

        return height;
    }


    public override void OnGUI(Rect position, SerializedProperty property, GUIContent label)
    {
        EditorGUI.BeginProperty(position, label, property);

        float line = EditorGUIUtility.singleLineHeight;
        float gap = EditorGUIUtility.standardVerticalSpacing;

        property.isExpanded = EditorGUI.Foldout(
            new Rect(position.x, position.y, position.width, line), property.isExpanded, label, true);

        if (!property.isExpanded)
        {
            EditorGUI.EndProperty();
            return;
        }

        int indent = EditorGUI.indentLevel;
        EditorGUI.indentLevel = 0;

        SerializedProperty slots = property.FindPropertyRelative("Slots");
        if (slots.arraySize != TerrainEdges.SLOT_COUNT) slots.arraySize = TerrainEdges.SLOT_COUNT;

        float x = position.x + 14.0f;
        float y = position.y + line + gap;

        foreach (Section section in Layout)
        {
            EditorGUI.LabelField(new Rect(x, y, position.width, line), section.title, EditorStyles.boldLabel);
            y += line;
            EditorGUI.LabelField(new Rect(x, y, position.width, line), section.hint, EditorStyles.miniLabel);
            y += line + gap;

            for (int i = 0; i < section.cells.Length; i++)
            {
                Cell cell = section.cells[i];
                if (cell.slot == GAP) continue;

                Rect rect = new Rect(
                    x + (i % section.columns) * (CELL + gap),
                    y + (i / section.columns) * (RowHeight() + gap),
                    CELL, CELL);

                if (cell.slot == FILL_PREVIEW) DrawFillPreview(rect, property, cell);
                else DrawSlot(rect, slots.GetArrayElementAtIndex(cell.slot), cell);
            }

            int rows = Mathf.CeilToInt(section.cells.Length / (float)section.columns);
            y += rows * (RowHeight() + gap) + gap;
        }

        EditorGUI.indentLevel = indent;
        EditorGUI.EndProperty();
    }


    private static float RowHeight()
    {
        return CELL + EditorGUIUtility.standardVerticalSpacing + DIAGRAM;
    }


    private static void DrawSlot(Rect rect, SerializedProperty sprite, Cell cell)
    {
        using (new EditorGUI.DisabledScope(cell.note != null))
        {
            EditorGUI.ObjectField(rect, sprite, typeof(Sprite), GUIContent.none);
        }

        DrawDiagram(DiagramRect(rect), TerrainEdges.ShapeForSlot(cell.slot));

        string tip = TerrainEdges.SlotNames[cell.slot];
        if (cell.note != null) tip += " (" + cell.note + ")";

        GUI.Label(rect, new GUIContent(string.Empty, tip));
    }


    // The middle of the ring is a surrounded cell, which never reads a slot - it takes a random
    // Variant. Showing the first one keeps the ring looking like a page out of the tileset
    private static void DrawFillPreview(Rect rect, SerializedProperty property, Cell cell)
    {
        SerializedProperty variants = property.serializedObject.FindProperty("Variants");
        Sprite first = variants != null && variants.isArray && variants.arraySize > 0
            ? variants.GetArrayElementAtIndex(0).objectReferenceValue as Sprite
            : null;

        using (new EditorGUI.DisabledScope(true))
        {
            EditorGUI.ObjectField(rect, first, typeof(Sprite), false);
        }

        DrawDiagram(DiagramRect(rect), 0xFF);

        GUI.Label(rect, new GUIContent(string.Empty, "interior (" + cell.note + ")"));
    }


    private static Rect DiagramRect(Rect cell)
    {
        return new Rect(
            cell.x + (CELL - DIAGRAM) * 0.5f,
            cell.yMax + EditorGUIUtility.standardVerticalSpacing,
            DIAGRAM, DIAGRAM);
    }


    private static readonly int[] PipBits =
    {
        NW, N, NE,
        W, 0, E,
        SW, S, SE,
    };


    private static void DrawDiagram(Rect area, int shape)
    {
        for (int i = 0; i < PipBits.Length; i++)
        {
            Rect pip = new Rect(
                area.x + (i % 3) * (PIP + PIP_GAP),
                area.y + (i / 3) * (PIP + PIP_GAP),
                PIP, PIP);

            int bit = PipBits[i];

            if (bit == 0) EditorGUI.DrawRect(pip, Centre);
            else if ((shape & bit) != 0) EditorGUI.DrawRect(pip, Filled);
            else if (TerrainEdges.IsDiagonalMoot(shape, bit)) EditorGUI.DrawRect(pip, Moot);
            else EditorGUI.DrawRect(pip, Empty);
        }
    }
}
